<template><main class="mx-auto max-w-2xl px-4 py-16"><div class="rounded-2xl border bg-white p-8 text-center shadow-sm"><h1 class="text-2xl font-black">Restore your Kialla Computers cart</h1><p class="mt-3 text-slate-600">{{ message }}</p><NuxtLink v-if="done" to="/shoppingcart" class="mt-6 inline-flex rounded-xl bg-blue-600 px-5 py-3 font-bold text-white">Return to your cart</NuxtLink></div></main></template>
<script setup lang="ts">const route=useRoute(),cart=useCartStore(),done=ref(false),message=ref('Restoring your products…');onMounted(async()=>{try{const r:any=await $fetch(`/api/cart/recover/${encodeURIComponent(String(route.params.token))}`);cart.restoreCart(r.items||[]);done.value=true;message.value='Your saved products have been restored. Review your cart and continue when you are ready.'}catch(e:any){message.value=e?.data?.statusMessage||'This recovery link is no longer available.'}});</script>
